#!/usr/bin/env python3
"""Build a self-contained T05 dashboard preview from accepted T03/T04 outputs."""
from __future__ import annotations

import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "reports" / "t05"
MONTHLY = ROOT / "reports/t03/sql/monthly_portfolio.csv"


def load_csv(path: Path) -> list[dict[str, str]]:
    with path.open(newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    datasets = {
        "monthly": load_csv(MONTHLY),
        "segment": load_csv(ROOT / "reports/t03/sql/risk_segment.csv"),
        "delinquency": load_csv(ROOT / "reports/t03/sql/delinquency_state.csv"),
        "vintage": load_csv(ROOT / "reports/t03/sql/vintage_mob.csv"),
        "roll": load_csv(ROOT / "reports/t03/sql/roll_rates.csv"),
        "context": load_csv(ROOT / "reports/t04/portfolio_context_joined.csv"),
        "scenarios": load_csv(ROOT / "reports/t04/scenario_results.csv"),
        "sensitivity": load_csv(ROOT / "reports/t04/scenario_sensitivity.csv"),
    }
    payload = json.dumps(datasets, separators=(",", ":"), ensure_ascii=False)
    html = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>UK Credit Portfolio | Monthly Review</title>
<style>
:root{--ink:#152638;--muted:#5e7182;--line:#dce5e9;--paper:#f4f7f8;--white:#fff;--teal:#087e83;--blue:#456f9c;--orange:#cb7c28;--red:#b44646;--green:#32856b}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1450px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.eyebrow{font-weight:700;color:var(--teal);letter-spacing:.11em;text-transform:uppercase;font-size:11px}.title{font-size:28px;line-height:1.15;margin:6px 0}.sub{color:var(--muted);margin:0}.badge{background:#fff3dc;color:#785418;border:1px solid #ecd6a8;border-radius:99px;padding:7px 12px;font-weight:700;font-size:11px;white-space:nowrap}.toolbar{display:flex;align-items:center;gap:8px;margin:20px 0 14px;color:var(--muted)}select{border:1px solid var(--line);border-radius:8px;background:white;padding:8px 12px;color:var(--ink);font:inherit}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card,.panel{background:var(--white);border:1px solid var(--line);border-radius:12px;box-shadow:0 2px 7px #19313d08}.card{padding:15px 17px}.label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}.value{font-size:25px;font-weight:700;margin:5px 0 1px;letter-spacing:-.03em}.delta{font-size:12px;color:var(--muted)}.panel{padding:16px;margin-top:12px}.panel h2{font-size:15px;margin:0 0 2px}.hint{font-size:11px;color:var(--muted);margin:0 0 8px}.twocol{display:grid;grid-template-columns:1.45fr 1fr;gap:12px}.threecol{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}.chart{width:100%;height:230px;display:block}.chart.small{height:205px}.legend{font-size:11px;color:var(--muted);display:flex;gap:14px;flex-wrap:wrap}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}.tables{width:100%;border-collapse:collapse;font-size:12px}.tables th,.tables td{text-align:right;padding:8px 6px;border-bottom:1px solid #edf1f3}.tables th:first-child,.tables td:first-child{text-align:left}.tables th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.05em}.scenarios{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.scenario{border:1px solid var(--line);border-radius:9px;padding:11px}.scenario b{display:block;font-size:12px}.scenario strong{font-size:18px;display:block;margin:4px 0}.scenario span{font-size:11px;color:var(--muted)}.note{border-left:3px solid var(--orange);padding:8px 11px;color:#4b5d68;background:#fbfaf6;font-size:11px;margin-top:12px}.foot{margin:14px 2px;color:var(--muted);font-size:10px}.error{color:var(--red)}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.twocol,.threecol{grid-template-columns:1fr}.wrap{padding:14px}.title{font-size:23px}}
</style></head><body><main class="wrap">
<header class="top"><div><div class="eyebrow">Portfolio intelligence · monthly credit review</div><h1 class="title">UK Consumer Credit Portfolio</h1><p class="sub">Synthetic monthly account snapshots · January 2022 to September 2026</p></div><div class="badge">ILLUSTRATIVE SYNTHETIC DATA</div></header>
<div class="toolbar"><label for="month">Review month</label><select id="month" aria-label="Review month"></select><span id="periodNote"></span></div>
<section class="grid" id="kpis"></section>
<section class="twocol"><article class="panel"><h2>Portfolio trend</h2><p class="hint">Latest 12 observed months through selected review month · GBP</p><div class="legend"><span><i class="dot" style="background:#087e83"></i>Active balance</span><span><i class="dot" style="background:#456f9c"></i>Credit limit</span></div><svg class="chart" id="trend" viewBox="0 0 760 230" role="img" aria-label="Portfolio balance and credit limit trend"></svg></article>
<article class="panel"><h2>Risk indicators</h2><p class="hint">Rates use active accounts or active balance denominators</p><div class="legend"><span><i class="dot" style="background:#cb7c28"></i>Simulated 30+ account rate</span><span><i class="dot" style="background:#b44646"></i>Simulated 30+ balance rate</span></div><svg class="chart" id="riskTrend" viewBox="0 0 520 230" role="img" aria-label="Simulated delinquency trend"></svg></article></section>
<section class="threecol"><article class="panel"><h2>Active book by risk segment</h2><p class="hint">Selected month · segment labels are generator-defined</p><div id="segments"></div></article><article class="panel"><h2>Delinquency proxy mix</h2><p class="hint">Selected month · generated status buckets, not arrears aging</p><svg class="chart small" id="mix" viewBox="0 0 420 205" role="img" aria-label="Delinquency proxy distribution"></svg></article><article class="panel"><h2>UK market context</h2><p class="hint">Official Bank of England indicators for selected month</p><div id="context"></div></article></section>
<section class="panel"><h2>Illustrative 12-month rate sensitivity</h2><p class="hint">September 2026 anchor · closing balance held constant; all balances assumed interest-bearing and repriced immediately</p><div id="scenarios" class="scenarios"></div><div class="note">These are mechanical annualized interest-cost proxies on a synthetic balance. Rate shocks are independent assumptions; no Bank Rate pass-through is fitted. Not a forecast, loss estimate, or customer-level outcome.</div></section>
<p class="foot">Source tables: T03 validated SQL outputs and T04 sourced context/scenario outputs. See <code>source_to_output_map.md</code> and <code>powerbi/</code> for lineage and Power BI import instructions. Snapshot rates and balances are descriptive of the synthetic generator only.</p>
</main><script>const D=__DATA__;
const n=(x)=>Number(x||0), gbp=(pence)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n(pence)/100), pct=(x,d=2)=>(n(x)*100).toFixed(d)+'%', num=(x)=>new Intl.NumberFormat('en-GB').format(n(x));
const months=D.monthly.map(x=>x.snapshot_month), sel=document.getElementById('month'); months.forEach((m,i)=>{let o=document.createElement('option');o.value=m;o.textContent=new Date(m+'T00:00:00').toLocaleDateString('en-GB',{month:'short',year:'numeric'});sel.append(o)});sel.value=months.at(-1);
function line(svgId,rows,series,labels){let svg=document.getElementById(svgId),w=svg.viewBox.baseVal.width,h=svg.viewBox.baseVal.height,p={l:43,r:10,t:12,b:29},W=w-p.l-p.r,H=h-p.t-p.b;let all=series.flatMap(s=>rows.map(r=>n(s.get(r))));let min=Math.min(0,...all),max=Math.max(...all)*1.1||1;let x=i=>p.l+(rows.length<2?0:i*W/(rows.length-1)),y=v=>p.t+H-(v-min)*H/(max-min||1);let out='';for(let k=0;k<4;k++){let v=min+(max-min)*k/3,yy=y(v);out+=`<path d="M${p.l} ${yy}H${w-p.r}" stroke="#e7edef"/><text x="${p.l-5}" y="${yy+4}" text-anchor="end" fill="#71818b" font-size="9">${labels.axis(v)}</text>`}series.forEach(s=>{let pts=rows.map((r,i)=>`${x(i)},${y(n(s.get(r)))}`).join(' ');out+=`<polyline points="${pts}" fill="none" stroke="${s.color}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>`;rows.forEach((r,i)=>{if(i===rows.length-1||i%3===0)out+=`<circle cx="${x(i)}" cy="${y(n(s.get(r)))}" r="3" fill="${s.color}"/>`})});rows.forEach((r,i)=>{if(i%Math.ceil(rows.length/4)===0||i===rows.length-1)out+=`<text x="${x(i)}" y="${h-7}" text-anchor="middle" fill="#71818b" font-size="9">${r.snapshot_month.slice(2,7)}</text>`});svg.innerHTML=out}
function render(){let m=sel.value,i=months.indexOf(m),r=D.monthly[i],prev=D.monthly[Math.max(i-1,0)],rows=D.monthly.slice(Math.max(0,i-11),i+1);document.getElementById('periodNote').textContent='· '+(i+1)+' of '+months.length+' observations';let kpis=[['Active balance',gbp(r.active_balance_pence),`${gbp(n(r.active_balance_pence)-n(prev.active_balance_pence))} vs prior month`],['Active accounts',num(r.active_accounts),`${n(r.active_accounts)-n(prev.active_accounts)>=0?'+':''}${n(r.active_accounts)-n(prev.active_accounts)} vs prior month`],['Portfolio utilisation',pct(r.portfolio_utilisation),`${(n(r.portfolio_utilisation)-n(prev.portfolio_utilisation)*1)*100>=0?'+':''}${((n(r.portfolio_utilisation)-n(prev.portfolio_utilisation))*100).toFixed(2)} pp vs prior month`],['Simulated 30+ account rate',pct(r.simulated_30plus_account_rate),`${((n(r.simulated_30plus_account_rate)-n(prev.simulated_30plus_account_rate))*100).toFixed(2)} pp vs prior month`],['Simulated 30+ balance rate',pct(r.simulated_30plus_balance_rate),`${((n(r.simulated_30plus_balance_rate)-n(prev.simulated_30plus_balance_rate))*100).toFixed(2)} pp vs prior month`],['Payment rate',pct(r.payment_rate),`${((n(r.payment_rate)-n(prev.payment_rate))*100).toFixed(2)} pp vs prior month`],['30+ proxy balance',gbp(r.simulated_30plus_balance_pence),'Active balance in generated 30+ status buckets'],['Credit limit',gbp(r.active_limit_pence),'Active account limits']];document.getElementById('kpis').innerHTML=kpis.map(a=>`<article class="card"><div class="label">${a[0]}</div><div class="value">${a[1]}</div><div class="delta">${a[2]}</div></article>`).join('');
line('trend',rows,[{color:'#087e83',get:r=>n(r.active_balance_pence)/100},{color:'#456f9c',get:r=>n(r.active_limit_pence)/100}],{axis:v=>gbp(v*100)});line('riskTrend',rows,[{color:'#cb7c28',get:r=>n(r.simulated_30plus_account_rate)},{color:'#b44646',get:r=>n(r.simulated_30plus_balance_rate)}],{axis:v=>pct(v,1)});
let seg=D.segment.filter(x=>x.snapshot_month===m);document.getElementById('segments').innerHTML=`<table class="tables"><thead><tr><th>Segment</th><th>Accounts</th><th>Balance</th><th>30+ proxy</th></tr></thead><tbody>${seg.map(s=>`<tr><td>${s.risk_segment}</td><td>${num(s.active_accounts)}</td><td>${gbp(s.active_balance_pence)}</td><td>${pct(s.simulated_30plus_account_rate)}</td></tr>`).join('')}</tbody></table>`;
let ds=D.delinquency.filter(x=>x.snapshot_month===m);let order=['CURRENT','1_29','30_59','60_89','90_PLUS'];let colors=['#4b9a81','#79b7a0','#e6b45d','#db8955','#bd5a52'];let svg=document.getElementById('mix'),x=14,y=18,w=390,h=24,xx=x,total=n(r.active_accounts),out='';order.forEach((key,i)=>{let row=ds.find(a=>a.delinquency_status===key),val=row?n(row.active_accounts):0,ww=w*val/total;out+=`<rect x="${xx}" y="${y}" width="${ww}" height="${h}" fill="${colors[i]}"/>`;xx+=ww});order.forEach((key,i)=>{let row=ds.find(a=>a.delinquency_status===key),val=row?n(row.active_accounts):0;out+=`<circle cx="22" cy="${64+i*25}" r="5" fill="${colors[i]}"/><text x="36" y="${68+i*25}" font-size="11" fill="#536673">${key.replace('_','–')} <tspan fill="#152638" font-weight="700">${num(val)} (${total?pct(val/total,1):'0.0%'})</tspan></text>`});svg.innerHTML=out;
let c=D.context.find(x=>x.month_end===m);document.getElementById('context').innerHTML=c?`<table class="tables"><tbody><tr><td>Bank Rate, month end</td><td>${pct(c.boe_bank_rate_end_month_pct/100)}</td></tr><tr><td>Quoted card lending rate</td><td>${pct(c.boe_quoted_credit_card_rate_pct/100)}</td></tr><tr><td>Effective card rate</td><td>${pct(c.boe_effective_interest_charging_card_rate_pct/100)}</td></tr></tbody></table><p class="hint">UK market series; not portfolio-specific rates.</p>`:'No matched context row';
document.getElementById('scenarios').innerHTML=D.scenarios.map(s=>`<div class="scenario"><b>${s.scenario}</b><strong>${gbp(n(s.annualized_interest_cost_proxy_gbp)*100)}</strong><span>Rate ${s.scenario_effective_card_rate_pct}% · Δ ${gbp(n(s.change_vs_baseline_gbp)*100)} vs baseline</span></div>`).join('')}
sel.addEventListener('change',render);render();</script></body></html>'''.replace("__DATA__", payload)
    (OUT / "dashboard_preview.html").write_text(html, encoding="utf-8")
    print(f"Wrote {OUT / 'dashboard_preview.html'} ({len(html):,} bytes)")


if __name__ == "__main__":
    main()
